script:
frappe.ui.form.on('Label Printing', {
    item_code: function(frm) {
        if (!frm.doc.item_code) return;

        // Fetch Item and set UOM filter
        frappe.db.get_doc("Item", frm.doc.item_code).then(item => {
            let allowed_uoms = [];

            if (item.uoms && item.uoms.length > 0) {
                allowed_uoms = item.uoms.map(row => row.uom);
            } else if (item.stock_uom) {
                allowed_uoms = [item.stock_uom];
            }

            // Restrict UOM field to allowed UOMs
            frm.set_query("uom", () => {
                return {
                    filters: [["UOM", "name", "in", allowed_uoms]]
                };
            });

            // Optionally auto-set if only one UOM exists
            if (allowed_uoms.length === 1) {
                frm.set_value("uom", allowed_uoms[0]);
            }

            // Do NOT set barcode here — wait for UOM selection
            frm.set_value("barcode", ""); 
        });
    },

    uom: function(frm) {
        if (!frm.doc.item_code || !frm.doc.uom) return;

        // Fetch Item to get barcodes
        frappe.db.get_doc("Item", frm.doc.item_code).then(item => {
            if (item.barcodes && item.barcodes.length > 0) {
                // Find the barcode that matches the selected UOM
                let matched = item.barcodes.find(b => b.uom === frm.doc.uom);
                if (matched) {
                    frm.set_value("barcode", matched.barcode);
                } else {
                    frm.set_value("barcode", ""); // clear if no match
                }
            } else {
                frm.set_value("barcode", ""); // clear if no barcodes
            }
        });
    }
});

frappe.ui.form.on('Label Printing', {
    update_price_from_price_list: function(frm) {
        if (!frm.doc.item_code || !frm.doc.uom || !frm.doc.price_list) {
            frappe.msgprint(__('Please select Item, UOM and Price List first.'));
            return;
        }

        // Fetch Item Price
        frappe.db.get_value("Item Price", 
            {
                item_code: frm.doc.item_code,
                price_list: frm.doc.price_list,
                uom: frm.doc.uom
            },
            "price_list_rate"
        ).then(r => {
            if (r && r.message && r.message.price_list_rate) {
                frm.set_value("price_to_print", r.message.price_list_rate);
            } else {
                frappe.msgprint(__('No Price found for this Item, Price List and UOM.'));
            }
        });
    }
});

frappe.listview_settings['Stocker Stock Entries'] = {
    onload: function(listview) {
        listview.page.add_action_item(__('Create Stock Reconciliation'), function() {
            let selected = listview.get_checked_items();

            if (!selected.length) {
                frappe.msgprint(__('Please select at least one Stock Entry'));
                return;
            }

            frappe.call({
                method: "stocker.stocker.doctype.stocker_stock_entries.stocker_stock_entries.create_stock_reconciliation",
                args: {
                    entries: selected.map(d => d.name)
                },
                freeze: true,
                freeze_message: __("Creating Stock Reconciliation..."),
                callback: function(r) {
                    if (!r.exc && r.message) {
                        
                        frappe.msgprint({
                            title: __('Success'),
                            indicator: 'green',
                            message: __('Stock Reconciliation Created')
                        });

                       
                        listview.refresh();
                    }
                }
            });
        });
    }
};

frappe.ui.form.on('Stocker Stock Entries', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button(__('Create Stock Reconciliation'), function() {
                frappe.call({
                    method: "stocker.stocker.api.create_stock_reconciliation_doc",
                    args: {
                        entries: [frm.doc.name]
                    },
                    freeze: true,
                    freeze_message: __("Creating Stock Reconciliation..."),
                    callback: function(r) {
                        frappe.msgprint(r.message);
                        // if (!r.exc && r.message) {
                        //     // frappe.msgprint({
                        //     // title: __('Success'),
                        //     // indicator: 'green',
                        //     // message: __('Stock Reconciliation Created')
                        //     // });  // just show the text
                            
                        // }
                    }
                });
            });
        }
    }
});

frappe.ui.form.on('Stocker Stock Entries', {
    refresh: function(frm) {
        
        if (!frm.is_new()) {
            frm.set_df_property('system_qty', 'read_only', 1);
        }

        
        if (frm.doc.stock_reconciliation === 1) {
            frm.set_df_property('stock_reconciliation', 'read_only', 1);
        }

        // Show/hide data_tkrs field based on conditions
        frm.toggle_display('data_tkrs', frm.doc.qty === frm.doc.system_qty && frm.doc.stock_reconciliation === 1);
    },

    qty: function(frm) {
        frm.toggle_display('data_tkrs', frm.doc.qty === frm.doc.system_qty && frm.doc.stock_reconciliation === 1);
    },

    system_qty: function(frm) {
        frm.toggle_display('data_tkrs', frm.doc.qty === frm.doc.system_qty && frm.doc.stock_reconciliation === 1);
    },

    stock_reconciliation: function(frm) {
        frm.toggle_display('data_tkrs', frm.doc.qty === frm.doc.system_qty && frm.doc.stock_reconciliation === 1);
    }
});
